    assert parse_labels(" key1 = value1 ; key2=value2 ") == {"key1": "value1", "key2": "value2"}

    # Test case 3: Preserve additional '=' in value
    assert parse_labels("key1=value=with=equals;key2=value2") == {"key1": "value=with=equals", "key2": "value2"}

