    # Test case 5: Ignore entries with empty key
    assert parse_labels("=value1;key2=value2") == {"key2": "value2"}
    assert parse_labels(" =value1;key2=value$") == {"key2": "value$"}

    # Test case 6: Ignore entries with empty value
    assert parse_labels("key1=;key2=value2") == {"key2": "value2"}
