{"content":"def parse_labels(text: str) -> dict[str, str]:
    """Parse semicolon-separated key=value labels into a dictionary."""
    labels = {}
    if not text:
        return labels
    for item in text.split(";"):
        item = item.strip()
        if "=" not in item:
            continue
        parts = item.split("=", 1)
        key = parts[0].strip()
        value = parts[1].strip()
        if not key or not value:
            continue
        labels[key] = value
    return labels
