{"content":"from config_reader import read_settings

def test_read_settings():
    # Test basic functionality
    assert read_settings("key1: value1\nkey2: value2") == {"key1": "value1", "key2": "value2"}

    # Test whitespace stripping
    assert read_settings(" key1 :  value1 \nkey2:value2") == {"key1": "value1", "key2": "value2"}

    # Test colons in value
    assert read_settings("url: https://example.com\npath: /usr/bin") == {"url": "https://example.com", "path": "/usr/bin"}

    # Test last occurrence wins
    assert read_settings("key1: value1\nkey1: value2") == {"key1": "value2"}

    # Test comments and empty lines
    assert read_settings("# comment\n\nkey1: value1\n  # another comment\nkey2: value2") == {"key1": "value1", "key2": "value2"}

    # Test malformed lines (no colon)
    assert read_settings("malformed line\nkey1: value1") == {"key1": "value1"}

    # Test empty key or value after trimming
    assert read_settings(": value1\nkey1: \nkey2: value2\n  :  ") == {"key2": "value2"}

    # Test complex case
    input_text = """
    # This is a comment
    user: admin
    password: secret:password
    empty_val: 
    : empty_key
    valid_key: valid_value
    duplicate: first
    duplicate: second
    """
    expected = {
        "user": "admin",
        "password": "secret:password",
        "valid_key": "valid_value",
        "duplicate": "second"
    }
    assert read_settings(input_text) == expected

    print("All tests passed!")

if __name__ == "__main__":
    test_read_settings()
","path":"test_config_reader.py"}

{"content":"def read_settings(text: str) -> dict[str, str]:
    """Read a small colon-delimited settings file."""
    settings = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue

        if ":" in line:
            parts = line.split(":", 1)
            key = parts[0].strip()
            value = parts[1].strip()

            if key and value:
                settings[key] = value
    return settings
