{"content":"import heapq

def dependency_order(graph):
    """Return nodes in dependency order."""
    # Identify all nodes (keys and values)
    all_nodes = set(graph.keys())
    for prerequisites in graph.values():
        for prereq in prerequisites:
            all_nodes.add(prereq)

    in_degree = {node: 0 for node in all_nodes}
    adj = {node: [] for node in all_nodes}

    for u, prerequisites in graph.items():
        for v in prerequisites:
            # v is a prerequisite of u, so edge is v -> u
            adj[v].append(u)
            in_degree[u] += 1

    # Min-priority queue for alphabetical tie-breaking
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependency graph")

    return result
