def dependency_order(graph):
    """Return nodes in dependency order."""
    # Build adjacency list (prereq -> dependents) and calculate in-degrees
    adj = {}
    in_degree = {}
    all_nodes = set()

    for node, prerequisites in graph.items():
        all_nodes.add(node)
        if node not in in_degree:
            in_degree[node] = 0

        for prereq in prerequisites:
            all_nodes.add(prereq)
            if prereq not in adj:
                adj[prereq] = []
            adj[prereq].append(node)

            in_degree[node] = in_degree.get(node, 0) + 1
            if prereq not in in_degree:
                in_degree[prereq] = 0

    # Initialize heap with nodes having in-degree 0
    heap = [node for node in all_nodes if in_degree.get(node, 0) == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        if u in adj:
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(heap, v)

    if len(result) != len(all_nodes):
