{"content":"import heapq

def dependency_order(graph):
    """Return nodes in dependency order."""
    # graph is {node: [prerequisites]}

    # 1. Identify all nodes and calculate in-degrees
    in_degree = {}
    adj = {} # node -> list of dependents

    # Initialize all keys in in_degree
    for node in graph:
        if node not in in_degree:
            in_degree[node] = 0
        if node not in adj:
            adj[node] = []

    # Populate in_degree and adj using prerequisites
    for node, prerequisites in graph.items():
        for prereq in prerequisites:
            # Prereq is a dependency for 'node'
            if prereq not in in_degree:
                in_degree[prereq] = 0
                adj[prereq] = []

            in_degree[node] += 1
            adj[prereq].append(node)

    # 2. Initialize heap with nodes having in-degree 0
    ready_nodes = [node for node, degree in in_degree.items() if degree == 0]
    heapq.heapify(ready_nodes)

    result = []

    # 3. Process nodes
    while ready_nodes:
        u = heapq.heappop(ready_nodes)
        result.append(u)

        for v in adj.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready_nodes, v)

    # 4. Check for cycles
    if len(result) != len(in_degree):
        raise ValueError("Cycle detected in dependencies")

    return result
