{"path":"dependency_order.py","content":"def dependency_order(graph):
    """Return nodes in dependency order.

    Given a mapping from node to an iterable of prerequisite nodes, return 
    a deterministic topological order: prerequisites precede dependents and 
    tied ready nodes are alphabetical. Include prerequisites that appear only 
    as values. Raise ValueError for a cycle.
    """
    # Collect all nodes (both keys and values in the graph)
    all_nodes = set(graph.keys())
    for node, prereqs in graph.items():
        if isinstance(prereqs, str):
            # Handle string iterable case like "a b c" or similar
            pass  # already handled below

    # Build adjacency list and compute in-degrees
    all_nodes = set(graph.keys()) | {n for node in graph for n in (graph[node].split() if isinstance(graph[node], str) else graph[node])}

    # Rebuild with proper handling of iterables
    adj = {}  # node -> list of nodes that depend on it
    in_degree = {}  # node -> number of prerequisites

    all_nodes_set = set()
    for node, prereqs in graph.items():
