{"path": "dependency_order.py", "content": "import heapq


def dependency_order(graph):
    """Return nodes in dependency order.

    ``graph`` maps each node to an iterable of its prerequisite nodes.
    The returned order is deterministic: every prerequisite precedes its
    dependents, and among ready nodes (all prerequisites already ordered)
    the alphabetical one is chosen first. Prerequisites that appear only
    as values are included in the result.

    Raises ``ValueError`` if the graph contains a cycle.
    """
    nodes = set(graph)
    for prereqs in graph.values():
        nodes.update(prereqs)

    # in_degree[node] counts prerequisites not yet placed in the order.
    in_degree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            in_degree[node] += 1
            dependents[prereq].append(node)

    ready = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        raise ValueError("cycle detected in dependency graph")
    return order
