    # Check for leading 'v'
    if value.startswith('v') or value.startswith('V'):
        raise ValueError("Invalid version format: leading 'v' not allowed")

    # Check for suffix
    suffix = None
    if '-' in value:
        main_part, suffix = value.split('-', 1)
        if suffix == '':
            raise ValueError("Invalid version format: empty suffix not allowed")
    else:
        main_part = value

    # Split the main version parts
    parts = main_part.split('.')

    # Must have exactly 3 parts
    if len(parts) != 3:
        raise ValueError("Invalid version format: must be MAJOR.MINOR.PATCH")

    # Validate each part
    result = []
    for i, part in enumerate(parts):
        # Check for empty part
        if part == '':
            raise ValueError(f"Invalid version format: empty part at position {i}")

        # Check for leading zeroes (except for literal '0')
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Invalid version format: leading zeroes not allowed in part {i}")

        # Check that it's a valid non-negative integer
        try:
            num = int(part)
            if num < 0:
                raise ValueError(f"Invalid version format: negative number at position {i}")
        except ValueError:
            raise ValueError(f"Invalid version format: non-integer value at position {i}")

        result.append(num)

    return (result[0], result[1], result[2], suffix)
