def parse_version(value):
    """Parse version string in MAJOR.MINOR.PATCH[-suffix] format.

    Returns (major, minor, patch, suffix_or_none).
    Raises ValueError for invalid formats including:
    - Leading 'v' prefix
    - Missing parts
    - Extra dots
    - Empty suffixes or missing suffix after dash
    - Leading zeros in numeric parts (except single 0)
    """
    # Reject leading 'v'
    if value.startswith('v'):
        raise ValueError("Version cannot start with 'v'")

    # Split by dot and check for extra dots (more than 2 splits means >3 parts or empty strings from consecutive dots)
    parts = value.split('.')

    # Must have exactly 3 numeric parts before optional suffix
    if len(parts) != 3:
        raise ValueError("Version must have exactly MAJOR.MINOR.PATCH format")

    major, minor, patch_suffix_part = parts

    # Check for empty strings (from consecutive dots or trailing dot)
    if any(part == '' for part in [major, minor]):
        raise ValueError("Missing version component")

    # If there's a suffix marker (-), validate it properly
    has_suffix = False
    patch_part = patch_suffix_part

    if patch_suffix_part.startswith('-'):
        has_suffix = True
        suffix = patch_suffix_part[1:]  # Remove the '-' prefix

        # Check for empty suffix (trailing dash or just '-')
        if not suffix:
            raise ValueError("Empty suffix after dash")

        # Suffix can contain anything, but let's keep it as-is since no specific restriction mentioned
    else:
        patch_part = patch_suffix_part

    # Validate each numeric part for leading zeros and convert to int
    def validate_and_convert(part_name):
        if len(part) > 1 and part.startswith('0'):
            raise ValueError(f"Leading zero not allowed in {part_name}")

        try:
            return int(part)
        except ValueError as e:
            raise ValueError(f"{part_name} must be a valid integer") from e

    major_num = validate_and_convert("MAJOR", major)
    minor_num = validate_and_convert("MINOR", minor)

    # For patch, if there was no suffix marker but the part is just digits:
    if not has_suffix and len(patch_part) == 0 or (not has_suffix):
        raise ValueError("Missing PATCH component")

    try:
        patch_num = int(patch_part)
    except ValueError as e:
        # If it's a number with suffix, the suffix is after '-' 
        if not has_suffix:
            raise

        # This shouldn't happen given our logic above

    return (major_num, minor_num, patch_num, None if not has_suffix else suffix)
