{"content":"from pathlib import Path

def safe_child(base, candidate):
    candidate_path = Path(candidate)
    if candidate_path.is_absolute():
        raise ValueError("Absolute paths are not allowed")

    # Use resolve() to handle '..' and symlinks
    # We use absolute() first to ensure we have a full path before resolving
    base_path = Path(base).resolve()
    try:
        child_path = (base_path / candidate_path).resolve()
    except Exception:
        # Fallback if resolve fails for some reason (e.g. permission error)
        child_path = (base_path / candidate_path).absolute()

    if not child_path.is_relative_to(base_path):
        raise ValueError("Path is outside the base directory")

    return child_path
