from pathlib import Path

def test_safe_child_valid():
    base = Path("/tmp/foo").resolve()
    candidate = "bar"
    result = safe_child(base, candidate)
    assert result == (base / "bar").resolve()

def test_safe_child_subfolder():
    base = Path("/tmp/foo").resolve()
    candidate = "bar/baz"
    result = safe_child(base, candidate)
    assert result == (base / "bar/baz").resolve()

def test_safe_child_absolute_path():
    base = Path("/tmp/foo").resolve()
    candidate = "/tmp/bar"
    try:
        safe_child(base, candidate)
    except ValueError:
        return
    else:
        raise AssertionError("Should have raised ValueError for absolute path")

def test_safe_child_traversal_outside():
    base = Path("/tmp/foo").resolve()
    candidate = "../bar"
    try:
        safe_child(base, candidate)
    except ValueError:
        return
    else:
        raise AssertionError("Should have raised ValueError for traversal outside")

def test_safe_child_sibling_outside():
    base = Path("/tmp/foo").resolve()
    candidate = "../foo-other"
    try:
        safe_child(base, candidate)
    except ValueError:
        return
    else:
        raise AssertionError("Should have raised ValueError for sibling outside")

if __name__ == "__main__":
    test_safe_child_valid()
    test_safe_child_subfolder()
    test_safe_child_absolute_path()
    test_safe_child_traversal_outside()
    test_safe_child_sibling_outside()
