def test_clean_rows():
    test_cases = [
        {
            "input": [
                {"name": " Alice ", "email": " ALICE@example.com ", "score": "10"},
                {"name": "Bob", "email": "bob@example.com", "score": 20},
                {"name": "", "email": "no_name@example.com", "score": "30"},
                {"name": "Charlie", "email": "", "score": "40"},
                {"name": "Dave", "email": "dave@example.com", "score": "not_an_int"},
            ],
            "expected": [
                {"name": "Alice", "email": "alice@example.com", "score": 10},
                {"name": "Bob", "email": "bob@example.com", "score": 20},
            ]
        },
        {
            "input": [
                {"name": "  ", "email": "  ", "score": "5"}, # Should be discarded (empty name/email after trim)
            ],
            "expected": []
        }
    ]

    for i, case in enumerate(test_cases):
        result = clean_rows(case["input"])
        assert result == case["expected"], f"Test case {i} failed: expected {case['expected']}, got {result}"
        # Check for mutation
        import copy
        original_input = copy.deepcopy(case["input"])
        clean_rows(case["input"])
        assert case["input"] == original_input, f"Test case {i} failed: input was mutated"

    print("All tests passed!")

if __name__ == "__main__":
