{"content": "def duplicate_ids(records):
    """Return a sorted list of normalized string IDs that occur more than once.

    Normalizes by trimming and lowercasing; ignores missing, blank, and non-string IDs.
    """
    id_counts = {}

    for record in records:
        # Skip non-string IDs
        if not isinstance(record, str):
            continue

        # Normalize: trim and lowercase
        normalized_id = record.strip().lower()

        # Skip blank IDs after normalization
        if not normalized_id:
            continue

        # Count occurrences
        id_counts[normalized_id] = id_counts.get(normalized_id, 0) + 1

    # Return sorted list of IDs that occur more than once
    return sorted([id for id, count in id_counts.items() if count > 1])
