{"path": "reconcile.py", "content": "def reconcile(expected, actual):
    """Return ids whose counts differ between ``expected`` and ``actual``.

    Both arguments are mappings of id to integer count. A count missing
    from either mapping is treated as zero. The returned dict maps each
    differing id to ``{"expected": E, "actual": A}`` with keys in
    ascending id order. Non-integer counts raise ``ValueError``.
    """
    for value in (*expected.values(), *actual.values()):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("counts must be integers, got %r" % (value,))

    result = {}
    for key in sorted(set(expected) | set(actual)):
        e = expected.get(key, 0)
        a = actual.get(key, 0)
        if e != a:
            result[key] = {"expected": e, "actual": a}
    return result
