{"path": "reconcile.py", "content": "def reconcile(expected, actual):
    """Reconcile two id -> count mappings.

    Given ``expected`` and ``actual`` dictionaries mapping ids to integer
    counts, return a dictionary of the ids whose counts differ, each mapped
    to ``{"expected": E, "actual": A}``. Counts missing from either mapping
    are treated as zero. The returned dictionary's insertion order is sorted
    by id.

    Raises:
        ValueError: if any count in either mapping is not an integer
            (booleans and other non-int types are rejected).
    """
    for mapping in (expected, actual):
        for key, count in mapping.items():
            if not isinstance(count, int) or isinstance(count, bool):
                raise ValueError(
                    "counts must be integers, got %r for id %r" % (count, key)
                )

    diffs = {}
    for key in sorted(set(expected) | set(actual)):
        e = expected.get(key, 0)
        a = actual.get(key, 0)
        if e != a:
            diffs[key] = {"expected": e, "actual": a}
    return diffs
