    result = []
    for value in values:
        # Check if it's a string
        if not isinstance(value, str):
            continue

        # Check if it matches the exact YYYY-MM-DD pattern with zero-padding
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', value):
            continue

        # Try to parse as a valid date
        try:
            parts = value.split('-')
            year = int(parts[0])
            month = int(parts[1])
            day = int(parts[2])

            # Validate ranges for zero-padding
            if month < 1 or month > 12:
                continue

            # Days vary by month
            if month in [1, 3, 5, 7, 8, 10, 12]:
                max_day = 31
            elif month in [4, 6, 9, 11]:
                max_day = 30
            elif month == 2:
                # Check for leap year
                is_leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
                max_day = 29 if is_leap else 28

            if day < 1 or day > max_day:
                continue

            # If we got here, it's a valid date
            result.append(value)
        except (ValueError, IndexError):
            continue

    return result
