def valid_dates(values):
    """Return a list of input strings that are valid calendar dates in exact YYYY-MM-DD form."""
    result = []

    for value in values:
        # Reject non-strings
        if not isinstance(value, str):
            continue

        # Check format is exactly YYYY-MM-DD with zero-padding (10 chars)
        if len(value) != 10 or value[4] != '-' or value[7] != '-':
            continue

        year_str = value[:4]
        month_str = value[5:7]
        day_str = value[8:]

        # Check zero-padding (no leading zeros stripped, must be exactly 2 digits each)
        if not all(c.isdigit() for c in year_str):
            continue
        if not all(c.isdigit() for c in month_str):
            continue
        if not all(c.isdigit() for c in day_str):
            continue

        # Check range constraints to ensure it's a valid date
        try:
            datetime(int(year_str), int(month_str), int(day_str))
        except ValueError:
            continue

        result.append(value)

    return result
