_DATE_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")


def valid_dates(values):
    """Return the input strings that are valid calendar dates.

    A value is kept only if it is a string in exact ``YYYY-MM-DD`` form
    (zero-padded month and day, ASCII digits) and denotes a real calendar
    date. Input order is preserved.
    """
    result = []
    for value in values:
        if not isinstance(value, str):
            continue
        if not _DATE_RE.match(value):
            continue
        year, month, day = (int(part) for part in value.split("-"))
        try:
            date(year, month, day)
        except ValueError:
            continue
        result.append(value)
    return result
