{"path": "schema_conversion.py", "content": "def to_rows(columns):
    """Convert a mapping of column name to equal-length value lists into rows.

    Returns a list of row dictionaries, one per element, preserving the
    input mapping's key order. Returns [] for an empty mapping. Raises
    ValueError when any value is not a list or column lengths differ.
    """
    if not columns:
        return []
    lengths = set()
    for name, values in columns.items():
        if not isinstance(values, list):
            raise ValueError("column {!r} must be a list".format(name))
        lengths.add(len(values))
    if len(lengths) > 1:
        raise ValueError("column lengths differ")
    n = lengths.pop()
    return [
        {name: values[i] for name, values in columns.items()}
        for i in range(n)
    ]
