{"path": "schema_conversion.py", "content": "def to_rows(columns):
    """Convert a mapping of column name to equal-length value lists into rows.

    Returns a list of row dictionaries (one per row) preserving the input
    mapping's key order. Returns ``[]`` for an empty mapping. Raises
    ``ValueError`` if any value is not a list or column lengths differ.
    """
    if not columns:
        return []

    lengths = {}
    for name, values in columns.items():
        if not isinstance(values, list):
            raise ValueError(
                "column {!r} must be a list, got {}".format(
                    name, type(values).__name__
                )
            )
        lengths[name] = len(values)

    expected = next(iter(lengths.values()))
    for name, length in lengths.items():
        if length != expected:
            raise ValueError(
                "column {!r} has length {}, expected {}".format(
                    name, length, expected
                )
            )

    return [
        {name: values[i] for name, values in columns.items()}
        for i in range(expected)
    ]
