{"path": "schema_conversion.py", "content": "def to_rows(columns):
    """Convert a mapping of column name to equal-length value lists into a
    list of row dictionaries.

    The input mapping's key order is preserved in each row dictionary.
    An empty mapping yields an empty list. A ``ValueError`` is raised when
    any value is not a list or when the column lengths differ.
    """
    if not columns:
        return []

    for name, values in columns.items():
        if not isinstance(values, list):
            raise ValueError(
                "column {!r} must map to a list, got {}".format(
                    name, type(values).__name__
                )
            )

    lengths = {len(values) for values in columns.values()}
    if len(lengths) > 1:
        raise ValueError(
            "column lengths differ: {}".format(
                ", ".join(
                    "{!r}={}".format(name, len(values))
                    for name, values in columns.items()
                )
            )
        )

    n = lengths.pop()
    return [
        {name: values[i] for name, values in columns.items()}
        for i in range(n)
    ]
