{"path":"dependency_order.py","content":"def dependency_order(graph):
    """Return nodes in dependency order."""

    # Collect all nodes (both keys and any prereqs mentioned)
    all_nodes = set()
    adj_list = {}  # node -> list of prerequisites

    for node, prereqs in graph.items():
        if isinstance(prereqs, str):
            prereq_set = set(p.strip() for p in prereqs.split())
        else:
            prereq_set = set(prereqs)

        all_nodes.add(node)
        adj_list[node] = prereq_set

    # Add any prerequisites that only appear as values (not keys)
    for node, prereqs in graph.items():
        if isinstance(prereqs, str):
            for p in prereqs.split():
                all_nodes.add(p.strip())
        else:
            for p in prereqs:
                all_nodes.add(p)

    # Build reverse adjacency (who depends on whom) and compute in-degrees
    dependents = {n: [] for n in all_nodes}  # node -> list of nodes that depend on it

    for node, prereq_set in adj_list.items():
        for p in prereq_set:
            if p in all_nodes:  # only count valid prerequisites
                dependents[p].append(node)

    # Compute initial in-degrees (number of unmet dependencies)
    in_degree = {n: len(adj_list.get(n, set())) for n in all_nodes}

    # Kahn's algorithm with alphabetical ordering
    result = []
    ready = sorted([n for n in all_nodes if in_degree[n] == 0])

    while ready:
        node = ready.pop(0)  # Take the first (alphabetically smallest due to sorting)
        result.append(node)

        # Update dependents' in-degrees - process alphabetically too for determinism
        new_ready_nodes = []
        sorted_dependents = sorted(dependents[node])
        for dependent in sorted_dependents:
            if dependent not in all_nodes:
                continue
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0 and dependent not in ready:
                new_ready_nodes.append(dependent)

        # Add newly available nodes, keeping list sorted
        for nd in sorted(new_ready_nodes):
            try:
                ready.insert(ready.index(nd), nd)
            except ValueError:
                pass

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
