def safe_child(base: str, candidate: str) -> Path:
    """Given a base directory and a candidate relative path, return the resolved 
    candidate Path only if it remains inside the resolved base. Reject absolute 
    paths and traversal outside the base with ValueError."""

    # Resolve both to canonical (absolute) forms following symlinks
    base_path = Path(base).resolve()

    try:
        joined_path = (base_path / candidate).resolve()
    except Exception as e:
        raise ValueError(f"Invalid path resolution") from None

    rejected_reasons = [
        "Candidate path is absolute",  # Already handled by resolve but let's be explicit
        f"Candidate resolves outside base directory: {joined_path} not under {base_path}",
    ]

    if joined_path != base_path and not str(joined_path).startswith(str(base_path)):
        raise ValueError(rejected_reasons[1])

    return joined_path
"}

