{"path":"csv_cleaner.py","content":"def clean_rows(rows):
    """Normalize selected CSV-style records."""
    cleaned = []
    for row in rows:
        name = row.get("name", "")
        email = row.get("email", "")
        score_raw = row.get("score")

        # Check if values are non-empty and parse score as int
        if not name or not email:
            continue

        try:
            score = int(score_raw)
        except (ValueError, TypeError):
            continue

        cleaned.append({
            "name": name.strip(),
            "email": email.lower().strip(),
            "score": score
        })

    return cleaned
