{"path":"schema_conversion.py","content":"def to_rows(columns):
    # Handle empty mapping
    if not columns:
        return []

    # Check that all values are lists and get their length from first column
    for col_name, values in columns.items():
        if not isinstance(values, list):
            raise ValueError(f"Column '{col_name}' is not a list")

    # Get the expected length from first column (using next(iter(columns)) to preserve order)
    first_col = next(iter(columns))
    first_len = len(columns[first_col])

    # Check all lengths match and build rows
    for col_name, values in columns.items():
        if len(values) != first_len:
            raise ValueError(f"Column '{col_name}' has inconsistent length")

    # Build row dictionaries preserving key order (Python 3.7+ dicts preserve insertion order)
    rows = []
    for i in range(first_len):
        row = {k: v[i] for k, v in columns.items()}
        rows.append(row)

    return rows
"}

