{"path":"config_reader.py","content":"def read_settings(text: str) -> dict[str, str]:
    """Read a small colon-delimited settings file."""
    settings = {}
    for line in text.splitlines():
        if not line.strip() or line.startswith("#"):
            continue

        # Split on the first colon only to handle colons inside values
        idx = line.find(":")
        if idx == -1:
            continue  # malformed (no colon)

        key, value = line[:idx].strip(), line[idx+1:].strip()

        # Skip if key or value is empty after trimming
        if not key or not value:
            continue

        settings[key] = value

    return settings
"}

