adj = {node: set() for node in all_nodes}
for node, deps in graph.items():
    if isinstance(deps, (list, tuple)):
        for dep in deps:
            adj[dep].add(node)

print(f"adj: {dict(sorted((k,v) for k,v in sorted(adj.items())))}")

remaining_deps = {}
for node in all_nodes:
    if isinstance(graph.get(node), (list, tuple)):
        remaining_deps[node] = len(graph[node])
    else:
        remaining_deps[node] = 0

print(f"remaining_deps after init: {sorted([(k,v) for k,v in sorted(remaining_deps.items())])}")

queue = sorted([node for node in all_nodes if remaining_deps[node] == 0])
print(f"Initial queue: {queue}")

result = []
from bisect import insort_left
iteration = 0
while queue:
    current = queue.pop(0)
    print(f"Iteration {iteration}: pop current={current}, result now has {sorted(result)}, dependents of {current} are {adj[current]}")

    dependents = adj[current].copy()
    for dep in sorted(dependents):
        if remaining_deps[dep] > 0:
            print(f"   Decrementing {dep}: was {remaining_deps[dep]}, now {remaining_deps[dep]-1}")
            remaining_deps[dep] -= 1
            if remaining_deps[dep] == 0:
                insort_left(queue, dep)

    result.append(current)
    iteration += 1

print(f"Final queue (should be empty): {sorted(queue)}")
print(f"Result: {result}")
