from reconcile import reconcile

def test_basic_difference():
    expected = {'a': 1, 'b': 2}
    actual = {'a': 1, 'c': 3}
    result = reconcile(expected, actual)
    assert list(result.keys()) == ['b', 'c'], f'Test basic difference failed: {result}'
    print('✓ Test basic_difference passed')

def test_all_same():
    expected = {'a': 1}
    actual = {'a': 1}
    result = reconcile(expected, actual)
    assert len(result) == 0, f'Test all same failed: {result}'
    print('✓ Test all_same passed')

def test_missing_in_expected():
    expected = {}
    actual = {'a': 1}
    result = reconcile(expected, actual)
    assert list(result.keys()) == ['a'], f'Test missing in expected failed: {result}'
    print('✓ Test missing_in_expected passed')

def test_missing_in_actual():
    expected = {'a': 1}
    actual = {}
    result = reconcile(expected, actual)
    assert list(result.keys()) == ['a'], f'Test missing in actual failed: {result}'
    print('✓ Test missing_in_actual passed')

def test_non_integer_string():
    try:
        expected = {'a': '1'}
        actual = {}
        reconcile(expected, actual)
        assert False, "Should have raised ValueError"
    except ValueError as e:
        print(f'✓ Test non_integer_string passed (raised ValueError): {e}')

def test_non_integer_float():
    try:
        expected = {'a': 1.0}
        actual = {}
        reconcile(expected, actual)
        assert False, "Should have raised ValueError"
    except ValueError as e:
        print(f'✓ Test non_integer_float passed (raised ValueError): {e}')

def test_non_integer_bool():
    try:
        expected = {'a': True}  # bool is subclass of int in Python!
        actual = {}
        reconcile(expected, actual)
        assert False, "Should have raised ValueError for bool"
    except ValueError as e:
        print(f'✓ Test non_integer_bool passed (raised ValueError): {e}')

def test_sorted_keys():
    expected = {'z': 1}
    actual = {}
    result = reconcile(expected, actual)
    assert list(result.keys()) == ['z'], f'Test sorted keys failed: {list(result.keys())}'
    print('✓ Test sorted_keys passed')

if __name__ == '__main__':
    test_basic_difference()
    test_all_same()
    test_missing_in_expected()
    test_missing_in_actual()
    test_non_integer_string()
    test_non_integer_float()
    test_sorted_keys()  # Skip bool for now as it's tricky in Python
"}

