{"path":"config_reader.py","content":"def read_settings(text: str) -> dict[str, str]:
    """Read a small colon-delimited settings file."""
    settings = {}
    for line in text.splitlines():
        if not line.strip() or line.startswith("#"):
            continue
        # Strip whitespace from the entire line first to check if it's empty/comment
        stripped_line = line.strip()
        if ":" not in stripped_line:
            continue  # malformed line, no colon at all

        # Split only on the FIRST colon to retain colons inside values
        idx = stripped_line.index(":")
        key = stripped_line[:idx].strip()
        value = stripped_line[idx+1:].strip()

        # Skip if key or value is empty after trimming
        if not key or not value:
            continue

        settings[key] = value

    return settings
"}

