{"path":"dependency_order.py","content":"def dependency_order(graph):
    """Return nodes in dependency order."""
    # Collect all unique nodes from both keys and prerequisites (values)
    all_nodes = set()

    for node, prereqs in graph.items():
        if isinstance(prereqs, str):
            continue  # Skip non-iterable string values

        for p in prereqs:
            all_nodes.add(p)

        all_nodes.add(node)

