{"path":"dependency_order.py","content":"def dependency_order(graph):
    """Return nodes in dependency order.

    Given a mapping from node to an iterable of prerequisite nodes, return a 
    deterministic topological order: prerequisites precede dependents and tied 
    ready nodes are alphabetical. Include prerequisites that appear only as values.
    Raise ValueError for a cycle.
    """
    # Collect all nodes (both keys and any value in the graph)
    all_nodes = set(graph.keys())

    # Add all prerequisite nodes mentioned in values
    for node, prereqs in graph.items():
        if prereqs:
            for p in prereqs:
                all_nodes.add(p)

    # Build adjacency list and compute in-degrees
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, prereqs in graph.items():
        if not prereqs:
            continue
        for p in sorted(prereqs):  # Sort prerequisites to ensure determinism during build
            adj[node].append(p)
            in_degree[p] += 1

    # Kahn's algorithm with alphabetical ordering of ready nodes
    import heapq

    # Use a min-heap to always pick the alphabetically smallest node among those with 
    # zero in-degree (ready nodes)
    heap = []

    for node, degree in in_degree.items():
        if degree == 0:
            heapq.heappush(heap, node)

    result = []

    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        # For each neighbor that depends on 'current', decrement their in-degree
        for dependent in adj[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    # Check if we visited all nodes (cycle detection)
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
