{"path":"dependency_order.py","content":"def dependency_order(graph):
    """Return nodes in dependency order."""
    # Collect all nodes from both keys and values (prerequisites that only appear as values)
    all_nodes = set()
    for node, deps in graph.items():
        if not isinstance(deps, (list, tuple)):
            deps = [deps] if deps is not None else []
        all_nodes.add(node)
        all_nodes.update(deps)

    if not all_nodes:
        return list(all_nodes)  # Return empty list for no nodes

    # Build the dependency map with counts of incoming edges (prerequisites count)
    in_degree = {node: 0 for node in all_nodes}
    adj = {}  # adjacency list where we store nodes that depend on each prerequisite

    for node, deps in graph.items():
        if not isinstance(deps, (list, tuple)):
            deps = [deps] if deps is not None else []
        for dep in deps:
            all_nodes.add(dep)
            adj[dep].append(node)  # dep -> node means dep must come before node

    # Initialize in-degrees based on the graph edges (from keys to their dependencies' dependents)
    # Actually, we need to count how many prerequisites each node has
    for node, deps in graph.items():
        if not isinstance(deps, (list, tuple)):
            deps = [deps] if deps is not None else []
        for dep in deps:
            in_degree[node] += 1

    # Use a min-heap to process nodes with zero in-degree alphabetically
    import heapq

    ready_heap = [node for node in all_nodes if in_degree.get(node, 0) == 0]
    heapq.heapify(ready_heap)

    result = []

    while ready_heap:
        # Pop the smallest (alphabetically first) node with zero prerequisites
        current = heapq.heappop(ready_heap)
        result.append(current)

        # For each node that depends on this prerequisite, decrement its in-degree
        if current in adj:
            for dependent in sorted(adj[current]):  # Sort to ensure deterministic order when multiple become ready
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0 and dependent not in result and dependent not in [n for n, d in zip(result, [])]:
                    heapq.heappush(ready_heap, dependent)

    # Check for cycle: if we didn't process all nodes
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
