    """Return nodes in dependency order."""
    # Collect all unique nodes (both keys and values)
    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        all_nodes.update(deps)

    if not all_nodes:
        return []

    # Build adjacency list and compute in-degrees
    adj = {node: set(graph.get(node, [])) for node in sorted(all_nodes)}
    in_degree = {node: 0 for node in all_nodes}

    for node, deps in graph.items():
        for dep in deps:
            if dep in in_degree and node in in_degree:
                pass

    # Recompute properly - we need to track which edges exist
    # Reset adjacency based on actual dependencies
    adj = {node: set() for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, deps in graph.items():
        for dep in sorted(deps):
            if dep in all_nodes and node in all_nodes:
                # dep is a prerequisite of node (dep -> node)
                adj[dep].add(node)
                in_degree[node] += 1

    # Kahn's algorithm with alphabetical ordering
    ready = [node for node, degree in sorted(in_degree.items()) if degree == 0]

    result = []
    while ready:
        # Take the alphabetically first ready node
        ready.sort()
        current = ready.pop(0)
        result.append(current)

        # Update in-degrees of neighbors
        for neighbor in adj[current]:
            if neighbor in in_degree and in_degree[neighbor] > 0:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    ready.append(neighbor)

    # Check for cycle - if result doesn't include all nodes, there's a cycle
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
