    try:
        candidate_path = Path(candidate)
        if candidate_path.is_absolute():
            raise ValueError("Absolute paths are not allowed")

        full_path = resolved_base / str(candidate).lstrip('/')
        resolved_full_path = full_path.resolve()

        # Check if the resolved path is within base directory
        try:
            rel_to_base = (resolved_full_path.relative_to(resolved_base))
            return Path(str(rel_to_base))  # Return as relative to avoid absolute paths
        except ValueError:
            raise ValueError("Path traversal outside base detected") from None

    except Exception as e:
        if "is_absolute" in str(e) or isinstance(e, AttributeError):
            pass  # Fall through to manual check

        candidate_str = str(candidate).lstrip('/')

        full_path = resolved_base / candidate_str
        try:
            resolved_full_path = full_path.resolve()

            base_str = str(resolved_base) + os.sep
            if not (str(resolved_full_path).startswith(base_str)):
                raise ValueError("Path traversal outside base detected") from None

            return Path(str(full_path))  # Return relative path without resolving symlinks in result

    except Exception:
        pass

    # Final check with manual string comparison for robustness
    candidate_clean = str(candidate).lstrip('/') if isinstance(candidate, (str, os.PathLike)) else ""

    full_path_str = str(resolved_base / candidate_clean)
    try:
        resolved_full_path = Path(full_path_str).resolve()

        base_str = str(resolved_base) + os.sep

        # Handle edge case where path equals exactly the base (should be allowed as empty suffix?)
        if full_path_str == str(resolved_base):
