{"path":"event_normalizer.py","content":"def normalize_event(event):
    """Normalize a small analytics event."""
    if not event.get("event") or not event.get("user_id"):
        return None

    # Normalize event: trim and lowercase
    normalized_event = str(event["event"]).strip().lower()

    # Trim user_id (keep as string)
    trimmed_user_id = str(event["user_id"]).strip()

    if not trimmed_user_id or not normalized_event:
        return None

    # Process tags: handle both comma-separated strings and lists of strings
    raw_tags = event.get("tags", [])

    def normalize_tag(tag):
        """Normalize a single tag."""
        if isinstance(tag, str):
            return tag.strip().lower()
        elif hasattr(tag, '__iter__') and not isinstance(tag, (str, bytes)):
            # Handle iterable types like tuples/lists of strings
            for t in tag:
                normalize_tag(t)  # This won't work as written - let me reconsider

    tags = []

    if isinstance(raw_tags, str):
        # Comma-separated string
        parts = raw_tags.split(",")
        seen = set()
        for part in parts:
            normalized = part.strip().lower()
            if normalized and normalized not in seen:
                tags.append(normalized)
                seen.add(normalized)
    elif isinstance(raw_tags, list):
        # List of strings/tuples/etc.
        seen = set()
        for tag_item in raw_tags:
            if isinstance(tag_item, str):
                normalized = tag_item.strip().lower()
                if normalized and normalized not in seen:
                    tags.append(normalized)
                    seen.add(normalized)

    return {"event": normalized_event, "user_id": trimmed_user_id, "tags": tags}
