    """Normalize a small analytics event."""

    # Get raw values - check if missing (None) or blank ("") 
    raw_event = event.get("event")
    raw_user_id = event.get("user_id")

    # If either is None, return None immediately
    if raw_event is None:
        return None

    if raw_user_id is None:
        return None

    # Normalize event: trim whitespace then lowercase
    normalized_event = str(raw_event).strip().lower()

    # Check if event became empty after normalization (was blank like "   """)
    if not normalized_event or len(normalized_event) == 0:
        return None

    # Trim user_id and check for empty/blank
    trimmed_user_id = str(raw_user_id).strip()

    # If user_id is now empty string, return None
    if not trimmed_user_id or (hasattr(trimmed_user_id, '__len__') and len(trimmed_user_id) == 0):
        return None

    # Process tags - handle both comma-separated strings and lists of strings
    raw_tags = event.get("tags", [])

    def normalize_tag(tag):
        """Normalize a single tag to lowercase, trimmed non-empty string."""
        if isinstance(tag, str):
            cleaned = tag.strip().lower()
            return cleaned if len(cleaned) > 0 else None

    tags = []

    # Handle empty list case explicitly
    if not raw_tags:
        pass  # No valid tags to process
    elif isinstance(raw_tags, str):
        # Comma-separated string - split and process each part
        parts = raw_tags.split(",")
        seen = set()
        for part in parts:
            normalized = normalize_tag(part) if isinstance(part, str) else None
            if normalized is not None and len(normalized) > 0 and normalized not in seen:
                tags.append(normalized)
                seen.add(normalized)
    elif hasattr(raw_tags, '__iter__') and not isinstance(raw_tags, (str, bytes)):
        # List of strings/tuples/etc. - process each item
