        """Process a single tag and return it if valid."""
        if isinstance(tag, str):
            trimmed_lower = tag.strip().lower()
            if trimmed_lower:  # Non-empty after trimming
                return (trimmed_lower,)
        elif hasattr(tag, "__iter__") and not isinstance(tag, bytes):
            for item in tag:
                result = process_tag(item)
                if result:
                    yield from result
    # Actually let me simplify - handle string vs list properly

    tags_list = []

    if raw_tags is None or (isinstance(raw_tags, str) and not raw_tags.strip()):
        normalized_tags = []
    elif isinstance(raw_tags, str):
        # Comma-separated string
        for tag in raw_tags.split(","):
            trimmed_lower = tag.strip().lower()
            if trimmed_lower:  # Non-empty after trimming
                tags_list.append(trimmed_lower)
    else:
        # List of strings (or other iterable, but not bytes/string)
        seen = set()
        for item in raw_tags:
            if isinstance(item, str):
                trimmed_lower = item.strip().lower()
                if trimmed_lower and trimmed_lower not in seen:
                    tags_list.append(trimmed_lower)
