{"path":"reconcile.py","content":"def reconcile(expected, actual):
    # Collect all unique ids from both dictionaries
    all_ids = set(expected.keys()) | set(actual.keys())

    result = {}

    for id in sorted(all_ids):  # Sort by id to ensure consistent insertion order
        exp_count = expected.get(id, 0)
        act_count = actual.get(id, 0)

        # Validate that counts are integers (or integer-like values), reject non-integers/bools
        if isinstance(exp_count, bool):
            raise ValueError("Non-integer count found in 'expected'")
        if not isinstance(exp_count, int):
            try:
                exp_int = int(exp_count)
            except (TypeError, ValueError):
                raise ValueError(f"Non-integer count {exp_count!r} for id {id}")

            # Check that the float/int conversion is exact (no fractional part)
            if isinstance(exp_count, float) and not exp_count.is_integer():
                raise ValueError("Fractional count found in 'expected'")
        else:
            exp_int = exp_count

        if isinstance(act_count, bool):
            raise ValueError("Non-integer count found in 'actual'")
        if not isinstance(act_count, int):
            try:
                act_int = int(act_count)
            except (TypeError, ValueError):
                raise ValueError(f"Non-integer count {act_count!r} for id {id}")

            # Check that the float/int conversion is exact (no fractional part)
            if isinstance(act_count, float) and not act_count.is_integer():
                raise ValueError("Fractional count found in 'actual'")
        else:
            act_int = act_count

        # If counts differ, add to result with integer values for comparison
        if exp_int != act_int:
            result[id] = {"expected": int(exp_int), "actual": int(act_int)}

    return result
"}

