{"path":"schema_conversion.py","content":"def to_rows(columns):
    # Handle empty mapping - return empty list
    if not columns:
        return []

    # Check all values are lists and get their length from first column
    try:
        expected_length = len(list(next(iter(columns.values()))))
    except (TypeError, IndexError):
        raise ValueError("All column values must be non-empty or empty consistently")

    # Verify each value is a list with correct length
    for col_name, values in columns.items():
        if not isinstance(values, list):
            raise ValueError(f"Column '{col_name}' is not a list")
        if len(values) != expected_length:
            raise ValueError(f"Column lengths differ (expected {expected_length}, got {len(values)})")

    # Build rows - zip the column values to create dictionaries for each row
    result = []
    for i in range(expected_length):
        row = {}
        for col_name, values in columns.items():
            row[col_name] = values[i]
        result.append(row)

    return result
"}

