{"path":"schema_conversion.py","content":"def to_rows(columns):
    """Convert column mapping to list of row dictionaries."""

    # Return empty list for empty mapping
    if not columns:
        return []

    # Check that all values are lists and get their lengths
    col_lengths = {}
    for col_name, values in columns.items():
        if not isinstance(values, list):
            raise ValueError(f"Column '{col_name}' is not a list")
        col_lengths[col_name] = len(values)

    # Check that all non-empty columns have equal length
    empty_count = sum(1 for v in col_lengths.values() if v == 0)

    if empty_count == len(col_lengths):
        return []

    expected_len = max(col_lengths.values())

    # Verify no column has a different positive length than others
    non_empty_lens = [l for l in col_lengths.values() if l > 0]
    if non_empty_lens and not all(l == non_empty_lens[0] for l in non_empty_lens):
        raise ValueError("Column lengths differ")

    # Build rows
    rows = []
    for i in range(expected_len):
        row = {}
        for col_name, values in columns.items():
            if len(values) > 0 and i < len(values):
                row[col_name] = values[i]
        rows.append(row)

    return rows
